      "keystrokes": "cat > main.cpp <<'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n, m, k;\n    if(!(cin >> n >> m >> k)) return 0;\n    vector<vector<int>> adj(n+1);\n    for(int i = 0; i < m; ++i) {\n        int u, v; cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n\n    int L = (n + k - 1) / k; // minimal path length required\n\n    vector<int> depth(n+1, -1), parent(n+1, -1);\n    vector<char> vis(n+1, false);\n    vector<char> used(n+1, false); // vertex used as a cycle representative\n\n    struct Frame { int v; int idx; };\n    vector<vector<int>> dummy_back(n+1); // not strictly needed, kept for clarity\n    vector<Frame> st;\n    int root = 1;\n\n    vis[root] = true;\n    depth[root] = 0;\n    parent[root] = 0;\n    st.push_back({root, 0});\n\n    auto print_path = [&](int end)->void {\n        vector<int> path;\n        int x = end;\n        while(x != 0) {\n            path.push_back(x);\n            x = parent[x];\n        }\n        reverse(path.begin(), path.end());\n        cout << \"PATH\\n\";\n        cout << path.size() << \"\\n\";\n        for(size_t i = 0; i < path.size(); ++i) {\n            cout << path[i] << (i+1 == path.size() ? '\\n' : ' ');\n        }\n        exit(0);\n    };\n\n    auto print_cycles = [&](const vector<pair<int,int>>& cyc)->void {\n        cout << \"CYCLES\\n\";\n        for(const auto &p : cyc) {\n            int v = p.first, a = p.second;\n            // build cycle vertices by walking from v up to a via parent\n            vector<int> cycverts;\n            int t = v;\n            cycverts.push_back(t);\n            while(t != a) {\n                t = parent[t];\n                cycverts.push_back(t);\n            }\n            cout << cycverts.size() << \"\\n\";\n            for(size_t i = 0; i < cycverts.size(); ++i) {\n                cout << cycverts[i] << (i+1 == cycverts.size() ? '\\n' : ' ');\n            }\n        }\n        exit(0);\n    };\n\n    vector<pair<int,int>> cycles; // (v, a)\n    int cycles_found = 0;\n\n    while(!st.empty()) {\n        Frame &f = st.back();\n        int v = f.v;\n        if(f.idx < (int)adj[v].size()) {\n            int to = adj[v][f.idx++];\n            if(to == parent[v]) continue;\n            if(!vis[to]) {\n                vis[to] = true;\n                parent[to] = v;\n                depth[to] = depth[v] + 1;\n                st.push_back({to, 0});\n                // Check for long path on discovery\n                if(depth[to] >= L - 1) {\n                    print_path(to);\n                }\n            } else if(depth[to] < depth[v]) {\n                // back edge to ancestor\n                if(!used[v]) {\n                    int len = depth[v] - depth[to] + 1; // cycle length along tree path + edge (v,to)\n                    if(len % 3 != 0) {\n                        cycles.push_back({v, to});\n                        used[v] = true;\n                        cycles_found++;\n                        if(cycles_found == k) {\n                            print_cycles(cycles);\n                        }\n                    }\n                }\n                // otherwise ignore this back-edge for cycle generation\n            }\n        } else {\n            st.pop_back();\n        }\n    }\n\n    // If we reach here, no long path was found during DFS and fewer than k valid cycles found\n    if(cycles_found >= k) {\n        print_cycles(cycles);\n    } else {\n        cout << \"-1\\n\";\n    }\n\n    return 0;\n}\nCPP\n\ng++ -std=c++17 -O2 -pipe -static -s -o main main.cpp\n\n./main << EOF\n1 0 1\nEOF"], 
